// The castle texture manifest (#361, #363): small tileable and 9-slice PNGs
// generated by scripts/castle-textures.py from the tokens.json castle bases. Rails
// and corners carry the baked bevel and contact shadow; other orientations flip
// this art. Stone, the battlement and the ledge have torchlit-night generations;
// parchment and iron stay lit, so both schemes share that art.
import { useEffectiveScheme } from '@/theme/appearance';
import crenelStrip from '@/assets/castle/crenel-strip.png';
import crenelStripNight from '@/assets/castle/crenel-strip-night.png';
import ironFillArt from '@/assets/castle/iron-fill.png';
import ledgeStrip from '@/assets/castle/ledge-strip.png';
import ledgeStripNight from '@/assets/castle/ledge-strip-night.png';
import parchmentCorner from '@/assets/castle/parchment-corner.png';
import parchmentEdgeH from '@/assets/castle/parchment-edge-h.png';
import parchmentEdgeV from '@/assets/castle/parchment-edge-v.png';
import parchmentFill from '@/assets/castle/parchment-fill.png';
import stoneCorner from '@/assets/castle/stone-corner.png';
import stoneEdgeH from '@/assets/castle/stone-edge-h.png';
import stoneEdgeV from '@/assets/castle/stone-edge-v.png';
import stoneFill from '@/assets/castle/stone-fill.png';
import stoneNightCorner from '@/assets/castle/stone-night-corner.png';
import stoneNightEdgeH from '@/assets/castle/stone-night-edge-h.png';
import stoneNightEdgeV from '@/assets/castle/stone-night-edge-v.png';
import stoneNightFill from '@/assets/castle/stone-night-fill.png';

export const castleTextures = {
  parchment: { fill: parchmentFill, edgeH: parchmentEdgeH, edgeV: parchmentEdgeV, corner: parchmentCorner },
  stone: { fill: stoneFill, edgeH: stoneEdgeH, edgeV: stoneEdgeV, corner: stoneCorner },
  ironFill: ironFillArt,
  crenel: crenelStrip,
  ledge: ledgeStrip,
};

export const nightTextures = {
  stone: { fill: stoneNightFill, edgeH: stoneNightEdgeH, edgeV: stoneNightEdgeV, corner: stoneNightCorner },
  crenel: crenelStripNight,
  ledge: ledgeStripNight,
};

/** The stone set for the effective scheme: day stone, or the torchlit hall at night. */
export function useCastleArt() {
  const scheme = useEffectiveScheme();
  return scheme === 'dark' ? nightTextures : { stone: castleTextures.stone, crenel: castleTextures.crenel, ledge: castleTextures.ledge };
}

/** Frame rail width and corner size in the texture art; content padding must exceed the rail. */
export const CASTLE_EDGE = 12;
export const CASTLE_CORNER = 12;
